mapper.select:
SELECT o.id AS orderId, o.store_id AS storeId, s.name AS storeName, s.platform AS platform, o.platform_order_no AS platformOrderNo, o.buyer_name AS buyerName, o.status AS status, o.local_status AS localStatus, o.ship_time AS shipTime, rr.status AS requestStatus, rr.request_time AS requestTime, rr.message AS requestMessage FROM ecom_order o JOIN ecom_store s ON s.id = o.store_id LEFT JOIN ecom_review_request rr ON rr.order_id = o.id WHERE s.platform = #{platform} AND AND o.store_id = #{storeId}
AND (o.platform_order_no LIKE CONCAT('%', #{keyword}, '%') OR o.buyer_name LIKE CONCAT('%', #{keyword}, '%'))
AND (rr.id IS NULL OR rr.status = 'FAILED') AND rr.status = #{status} ORDER BY o.ship_time, o.order_time, o.id
